# Block 3: Fetch cancellation reasons from MICE API
def fetch_cancellation_reason(event_id, company_id):
    api_key = API_KEYS.get(str(company_id))
    if not api_key:
        return None, None
    try:
        r = requests.get(
            f"{MICE_BASE}/events/{event_id}/messages",
            headers={"Authorization": f"Basic {api_key}"},
            timeout=10
        )
        if r.status_code != 200:
            return None, None
        messages = r.json().get('data', [])
        reason = None
        note = None
        for msg in messages:
            if msg.get('type') != 'note':
                continue
            html = msg.get('message', '')
            strong_match = re.search(r'<strong>Geannuleerd:\s*([^<]+)<\/strong>', html)
            if not strong_match:
                continue
            reason = strong_match.group(1).strip()
            note_match = re.search(r'<\/strong><\/p><p>([^<]+)<\/p>', html)
            note = note_match.group(1).strip() if note_match else None
        return reason, note
    except Exception as e:
        print(f"⚠️ event {event_id}: {e}")
        return None, None


results = []
total = len(candidates)
found = 0
not_found = 0

for i, row in enumerate(candidates):
    reason, note = fetch_cancellation_reason(row['event_id'], row['company_id'])
    if reason:
        results.append({
            "event_id": int(row['event_id']),
            "cancellation_reason": reason,
            "cancellation_note": note or ""
        })
        found += 1
    else:
        not_found += 1

    if (i + 1) % 100 == 0:
        print(f"  [{i+1}/{total}] found: {found}, not found: {not_found}")

    time.sleep(0.1)

print(f"\n✓ Done: {found} reasons found, {not_found} without reason")
